"""Shared immutable recovery authority DDL for migration and legacy preparation."""

RECOVERY_IMMUTABILITY_SQL: tuple[str, ...] = (
    "CREATE FUNCTION expired_recovery_immutable_authority()\n    RETURNS trigger LANGUAGE plpgsql AS $$\n    BEGIN\n      IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'recovery authority is immutable'; END IF;\n      IF ROW(OLD.id,OLD.original_job_id,OLD.user_id,OLD.key_id,OLD.credential_version,\n             OLD.idempotency_key,OLD.request_sha256,OLD.intent_sha256,OLD.intent_payload,OLD.created_at)\n         IS DISTINCT FROM\n         ROW(NEW.id,NEW.original_job_id,NEW.user_id,NEW.key_id,NEW.credential_version,\n             NEW.idempotency_key,NEW.request_sha256,NEW.intent_sha256,NEW.intent_payload,NEW.created_at)\n      THEN RAISE EXCEPTION 'recovery authority is immutable'; END IF;\n      IF OLD.transfer_payload IS NOT NULL AND OLD.transfer_payload IS DISTINCT FROM NEW.transfer_payload\n      THEN RAISE EXCEPTION 'recovery transfer is immutable'; END IF;\n      IF OLD.consumption_payload IS NOT NULL AND OLD.consumption_payload IS DISTINCT FROM NEW.consumption_payload\n      THEN RAISE EXCEPTION 'recovery consumption is immutable'; END IF;\n      IF OLD.owner_claim_payload IS NOT NULL AND OLD.owner_claim_payload IS DISTINCT FROM NEW.owner_claim_payload\n      THEN RAISE EXCEPTION 'recovery owner claim is immutable'; END IF;\n      IF OLD.cold_claim_payload IS NOT NULL AND OLD.cold_claim_payload IS DISTINCT FROM NEW.cold_claim_payload\n      THEN RAISE EXCEPTION 'cold recovery owner claim is immutable'; END IF;\n      IF OLD.cold_smoke_payload IS NOT NULL AND OLD.cold_smoke_payload IS DISTINCT FROM NEW.cold_smoke_payload\n      THEN RAISE EXCEPTION 'cold recovery smoke authority is immutable'; END IF;\n      IF OLD.data_baseline_payload IS NOT NULL AND OLD.data_baseline_payload IS DISTINCT FROM NEW.data_baseline_payload\n      THEN RAISE EXCEPTION 'recovery data baseline is immutable'; END IF;\n      IF OLD.native_baseline_payload IS NOT NULL AND OLD.native_baseline_payload IS DISTINCT FROM NEW.native_baseline_payload\n      THEN RAISE EXCEPTION 'recovery native data baseline is immutable'; END IF;\n      IF OLD.cold_verification_payload IS NOT NULL AND OLD.cold_verification_payload IS DISTINCT FROM NEW.cold_verification_payload\n      THEN RAISE EXCEPTION 'cold recovery verification is immutable'; END IF;\n      IF OLD.cold_handback_intent_payload IS NOT NULL AND OLD.cold_handback_intent_payload IS DISTINCT FROM NEW.cold_handback_intent_payload\n      THEN RAISE EXCEPTION 'cold recovery handback intent is immutable'; END IF;\n      IF OLD.cold_handback_receipt_payload IS NOT NULL AND OLD.cold_handback_receipt_payload IS DISTINCT FROM NEW.cold_handback_receipt_payload\n      THEN RAISE EXCEPTION 'cold recovery handback receipt is immutable'; END IF;\n      IF OLD.resolution_payload IS NOT NULL AND OLD.resolution_payload IS DISTINCT FROM NEW.resolution_payload\n      THEN RAISE EXCEPTION 'recovery resolution is immutable'; END IF;\n      IF OLD.cancellation_payload IS NOT NULL AND OLD.cancellation_payload IS DISTINCT FROM NEW.cancellation_payload\n      THEN RAISE EXCEPTION 'recovery cancellation is immutable'; END IF;\n      RETURN NEW;\n    END $$",
    "CREATE TRIGGER expired_recovery_authority\n    BEFORE UPDATE OR DELETE ON upgrade_expired_recoveries FOR EACH ROW\n    EXECUTE FUNCTION expired_recovery_immutable_authority()",
    "CREATE FUNCTION recovery_succession_immutable_grant()\n    RETURNS trigger LANGUAGE plpgsql AS $$\n    BEGIN RAISE EXCEPTION 'recovery succession grant is immutable'; END $$",
    "CREATE TRIGGER recovery_succession_immutable\n    BEFORE UPDATE OR DELETE ON upgrade_recovery_successions\n    FOR EACH ROW EXECUTE FUNCTION recovery_succession_immutable_grant()",
    "CREATE FUNCTION recovery_successor_immutable_claim()\n    RETURNS trigger LANGUAGE plpgsql AS $$\n    BEGIN RAISE EXCEPTION 'recovery successor claim is immutable'; END $$",
    "CREATE TRIGGER recovery_successor_immutable\n    BEFORE UPDATE OR DELETE ON upgrade_recovery_successor_claims\n    FOR EACH ROW EXECUTE FUNCTION recovery_successor_immutable_claim()",
)
